{"path":"assets/css/styles.css","content":":root{
  --bg:#ffffff;
  --text:#0b1220;
  --muted:#6b7280;
  --accent:#0b7285;
  --surface:#f7fafc;
  --radius:8px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;color:var(--text);background:var(--bg);margin:0;line-height:1.5}
.wrap{max-width:var(--max-width);margin:0 auto;padding:32px}
.site-header{border-bottom:1px solid #eef2f7;background:linear-gradient(0deg,rgba(255,255,255,0.3),transparent)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--text);text-decoration:none}
.nav{margin-left:auto;display:flex;gap:18px;align-items:center}
.nav a{color:var(--muted);text-decoration:none}
.cta-btn{background:var(--accent);color:#fff;padding:8px 12px;border-radius:6px;text-decoration:none}
.nav-toggle{display:none;background:none;border:0;font-size:20px}

.hero{padding:56px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:32px;align-items:center}
.hero-copy h1{font-size:clamp(26px,4vw,40px);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 16px}
.hero-actions{display:flex;gap:12px;align-items:center;margin-bottom:12px}
.btn{padding:10px 16px;border-radius:8px;border:1px solid transparent;background:#fff;color:var(--text);cursor:pointer;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.muted{color:var(--accent);text-decoration:none}
.small{color:var(--muted);font-size:13px}
.hero-art img{width:100%;height:auto;display:block}

.values, .methods, .testimonials, .objections, .lead-magnet, .cta{padding:40px 0}
.values-grid{display:flex;gap:16px}
.card{background:var(--surface);padding:18px;border-radius:10px}
.methods-list{margin:12px 0 0}
.methods-list li{margin:8px 0;color:var(--muted)}
.test-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.test-grid blockquote{margin:0;padding:14px;background:#f6fbfb;border-left:4px solid var(--accent);border-radius:8px}
.faq-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px}
.simple-form{display:flex;gap:8px;align-items:center;margin-top:12px}
.simple-form input[type="email"]{padding:10px;border-radius:8px;border:1px solid #e6eef0;flex:1}

.cta-inner{display:flex;gap:20px;align-items:center;background:var(--surface);padding:18px;border-radius:10px}
.avatar{width:96px;height:96px}

.site-footer{border-top:1px solid #eef2f7;padding:20px 0}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.disclaimer{margin-top:12px;color:var(--muted)}

@media (max-width:800px){
  .hero-grid{grid-template-columns:1fr;}
  .values-grid{flex-direction:column}
  .test-grid{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  var navToggle=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.nav');
  if(navToggle){navToggle.addEventListener('click',function(){
    if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex';nav.style.flexDirection='column'}
  })}

  var leadForm=document.getElementById('leadForm');
  if(leadForm){leadForm.addEventListener('submit',function(e){
    e.preventDefault();
    var email=leadForm.querySelector('input[name="email"]').value;
    if(!email || !email.includes('@')){alert('Please enter a valid email.');return}
    // mimic async send
    leadForm.querySelector('button').disabled=true;
    leadForm.querySelector('button').textContent='Sending...';
    setTimeout(function(){
      leadForm.innerHTML='<p class="small">Thanks — the guide is on its way to '+email+'. Check your inbox (and promotions/junk).</p>';
    },900);
  })}

  // Smooth scroll for same-page anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id=this.getAttribute('href').slice(1);
      var el=document.getElementById(id);
      if(el)el.scrollIntoView({behavior:'smooth',block:'start'});
    })
  })
});"} 
